import { lazy } from "react";

const AllSubscribers = lazy(() => import("../../views/subscribers/all/index"));
const NewSubscriber = lazy(() => import("../../views/subscribers/new/index"));
const UpdateSubscriber = lazy(() =>
  import("../../views/subscribers/update/index")
);

const SubscribersRoutes = [
  {
    path: "/subscribers/all",
    element: <AllSubscribers />,
  },
  {
    path: "/subscribers/new",
    element: <NewSubscriber />,
  },
  {
    path: "/subscribers/update",
    element: <UpdateSubscriber />,
  },
];

export default SubscribersRoutes;
